#!/bin/bash
set -e

# Get the directory where this script is located
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# Extract DME sources
unzip -o DME.zip

# Use the Reference_Implementation tree (single parameter set: DME-KEM N=2,M=3,E=48,S=3)
REF="DME/Reference_Implementation"

# Install build dependencies (OpenSSL for rng.c AES-CTR DRBG)
apt-get update
apt-get install -y libssl-dev

# DME's dme.c #includes "setup.h", which is NOT shipped: it is generated by the
# upstream `setup/` makefile (find_best_exps + find_min_poly + find_m1_m2).
# These helpers use unseeded rand(), so the generation is deterministic across
# builds. Build the setup helpers and emit setup.h exactly as the upstream
# makefile does, without editing any upstream file.
(
  cd "$REF/setup"
  gcc -o find_best_exps find_best_exps.c bigint.c -Wall -Wextra -std=c99 -O3
  gcc -o find_min_poly find_min_poly.c -Wall -Wextra -std=c99 -O3
  ./find_best_exps > setup1.h
  ./find_min_poly >> setup1.h
  gcc -o find_m1_m2 find_m1_m2.c -Wall -Wextra -std=c99 -O3
  cat setup1.h > setup.h
  ./find_m1_m2 >> setup.h
)

# Copy the reference sources and the generated setup.h next to cli.c
cp "$REF"/*.c .
cp "$REF"/*.h .
cp "$REF/setup/setup.h" .

# Remove the KAT generation file (has its own main)
rm -f PQCgenKAT_kem.c

# Compile the CLI. dme.c needs C99 and the OpenSSL-backed DRBG in rng.c.
gcc -O3 -std=c99 -fcommon -o cli \
    cli.c dme.c rng.c \
    -I. -lssl -lcrypto

echo "Build complete. CLI binary created at: $SCRIPT_DIR/cli"
